// Bundles artifacts/api-server/src/app.ts into api/express.js.
// A small committed api/index.js wrapper imports this generated bundle so
// Vercel sees a real function at build-time while the bundle itself can still
// be generated by the existing monorepo build command.
//
// Deliberately bundles app.ts, not index.ts: index.ts calls app.listen()
// and reads a required PORT env var, both of which are wrong for a
// serverless function (Vercel owns the listener, and there is no PORT to
// set). app.ts just builds and exports the Express app.

import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build as esbuild } from "esbuild";
import esbuildPluginPino from "esbuild-plugin-pino";

globalThis.require = createRequire(import.meta.url);

const apiServerDir = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const repoRoot = path.dirname(path.dirname(apiServerDir));
const entry = path.join(apiServerDir, "src/app.ts");
const outdir = path.join(repoRoot, "api");
const outfile = path.join(outdir, "express.js");

await esbuild({
  entryPoints: { express: entry },
  platform: "node",
  bundle: true,
  format: "esm",
  outdir,
  logLevel: "info",
  external: [
    "*.node", "sharp", "better-sqlite3", "sqlite3", "canvas", "bcrypt",
    "argon2", "fsevents", "re2", "farmhash", "xxhash-addon", "bufferutil",
    "utf-8-validate", "ssh2", "cpu-features", "dtrace-provider", "isolated-vm",
    "lightningcss", "pg-native", "oracledb", "mongodb-client-encryption",
    "nodemailer", "handlebars", "knex", "typeorm", "protobufjs",
    "onnxruntime-node", "@tensorflow/*", "@prisma/client", "@mikro-orm/*",
    "@grpc/*", "@swc/*", "@aws-sdk/*", "@azure/*", "@opentelemetry/*",
    "@google-cloud/*", "@google/*", "googleapis", "firebase-admin",
    "@parcel/watcher", "@sentry/profiling-node", "@tree-sitter/*", "aws-sdk",
    "classic-level", "dd-trace", "ffi-napi", "grpc", "hiredis", "kerberos",
    "leveldown", "miniflare", "mysql2", "newrelic", "odbc", "piscina",
    "realm", "ref-napi", "rocksdb", "sass-embedded", "sequelize", "serialport",
    "snappy", "tinypool", "usb", "workerd", "wrangler", "zeromq",
    "zeromq-prebuilt", "playwright", "puppeteer", "puppeteer-core", "electron",
  ],
  sourcemap: false,
  plugins: [esbuildPluginPino({ transports: ["pino-pretty"] })],
  banner: {
    js: `import { createRequire as __bannerCrReq } from 'node:module';
import __bannerPath from 'node:path';
import __bannerUrl from 'node:url';

globalThis.require = __bannerCrReq(import.meta.url);
globalThis.__filename = __bannerUrl.fileURLToPath(import.meta.url);
globalThis.__dirname = __bannerPath.dirname(globalThis.__filename);
    `,
  },
}).catch((err) => {
  console.error(err);
  process.exit(1);
});

console.log(`Bundled Vercel API function -> ${path.relative(repoRoot, outfile)}`);

const fs = await import("node:fs/promises");
await fs.writeFile(
  path.join(outdir, "package.json"),
  JSON.stringify({ type: "module" }, null, 2) + "\n",
);
console.log(`Wrote ${path.relative(repoRoot, path.join(outdir, "package.json"))}`);
